type DetailValues = Record<string, string>;
type CostForm = {
  costCategoryId: string; costSupplierId: string; title: string; description: string; quantity: string; unit: string; amount: string;
  sourceReference: string; sourceUrl: string; details: DetailValues;
};

const EMPTY_FORM: CostForm = { costCategoryId: "", costSupplierId: "", title: "", description: "", quantity: "", unit: "", amount: "", sourceReference: "", sourceUrl: "", details: {} };
const MONEY_PATTERN = /^\d+(?:\.\d{1,5})?$/;
const SPECIALIZED_CODES = new Set(["AIRFARE", "BAGGAGE", "LODGING", "TRANSPORTATION", "TOUR", "INSURANCE", "EVENT_TICKET", "VISA_ASSISTANCE", "MEALS"]);
const ENUM_LABELS: Record<string, string> = {
  INTERNAL: "Interno", INTERNATIONAL: "Internacional", ONE_WAY: "Solo ida", ROUND_TRIP: "Ida y vuelta",
  ECONOMY: "Económica", PREMIUM_ECONOMY: "Económica premium", BUSINESS: "Ejecutiva", FIRST: "Primera", 
  CHECKED: "Equipaje documentado", CARRY_ON: "Carry on", EXCESS: "Exceso de equipaje", SPORTS_EQUIPMENT: "Equipo deportivo", OTHER: "Otro",
  HOTEL: "Hotel", HOSTEL: "Hostel", AIRBNB: "Airbnb", APARTMENT: "Apartamento", SINGLE: "Individual", MATRIMONIAL: "Matrimonial", DOUBLE: "Doble", TRIPLE: "Triple", QUADRUPLE: "Cuádruple",
  PRIVATE_TRANSFER: "Traslado privado", SHARED_SHUTTLE: "Shuttle / traslado compartido", BUS: "Autobús", TRAIN: "Tren", FERRY: "Ferry", TAXI_LOCAL: "Taxi / transporte local", RENTAL_CAR: "Vehículo de alquiler", SHARED_TRANSFER: "Shuttle / traslado compartido", CAR_RENTAL: "Vehículo de alquiler", RAIL: "Tren",
  HALF_DAY: "Medio día", FULL_DAY: "Día completo", MULTI_DAY: "Varios días",
  MEDICAL: "Médica", CANCELLATION: "Cancelación", TRIP_CANCELLATION: "Cancelación", BAGGAGE: "Equipaje", COMPREHENSIVE: "Integral", TOURISM: "Turismo", TOURIST: "Turismo", TRANSIT: "Tránsito", STUDENT: "Estudios", WORK: "Trabajo",
  BREAKFAST: "Desayuno", LUNCH: "Almuerzo", DINNER: "Cena", HALF_BOARD: "Media pensión", FULL_BOARD: "Pensión completa", ALL_INCLUSIVE: "Todo incluido",
};
const ENUMS = {
  flightType: ["INTERNAL", "INTERNATIONAL"], tripType: ["ONE_WAY", "ROUND_TRIP"], cabinClass: ["ECONOMY", "PREMIUM_ECONOMY", "BUSINESS", "FIRST", "OTHER"], baggageType: ["CHECKED", "CARRY_ON", "EXCESS", "SPORTS_EQUIPMENT", "OTHER"],
  lodgingType: ["HOTEL", "HOSTEL", "AIRBNB", "APARTMENT", "OTHER"], roomType: ["SINGLE", "MATRIMONIAL", "DOUBLE", "TRIPLE", "QUADRUPLE", "OTHER"], transportationType: ["PRIVATE_TRANSFER", "SHARED_SHUTTLE", "BUS", "TRAIN", "FERRY", "TAXI_LOCAL", "RENTAL_CAR", "OTHER"], tourType: ["HALF_DAY", "FULL_DAY", "MULTI_DAY", "OTHER"],
  coverageType: ["MEDICAL", "CANCELLATION", "BAGGAGE", "COMPREHENSIVE", "OTHER"], visaType: ["TOURISM", "BUSINESS", "TRANSIT", "STUDENT", "WORK", "OTHER"], mealPlanType: ["BREAKFAST", "LUNCH", "DINNER", "HALF_BOARD", "FULL_BOARD", "ALL_INCLUSIVE", "OTHER"],
} as const;
const OPTIONAL_DETAIL_FIELDS: Record<string, readonly string[]> = {
  AIRFARE: ["returnDate", "airline", "cabinClass"], BAGGAGE: ["weightKg"],
  TRANSPORTATION: ["serviceTime", "returnDate"], TOUR: ["duration"], INSURANCE: ["coverageAmount"], MEALS: ["endDate"],
};

export function GenericCostComposition({ costingProjectId, baseCurrency, canEdit, contextLabel, refreshToken = 0, onCompositionChanged }: {
  costingProjectId: string;
  baseCurrency: string;
  canEdit: boolean;
  contextLabel?: string;
  refreshToken?: number;
  onCompositionChanged?: (composition: CostComposition) => void;
}) {
  const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null); const [project, setProject] = useState<CostingProject | null>(null);
  const [composition, setComposition] = useState<CostComposition | null>(null); const [categories, setCategories] = useState<CostCategory[]>([]); const [suppliers, setSuppliers] = useState<CostSupplier[]>([]);
  const [form, setForm] = useState<CostForm>(EMPTY_FORM); const [selectedComponentId, setSelectedComponentId] = useState<string | null>(null); const [initialSnapshot, setInitialSnapshot] = useState<CostSnapshot | null>(null);
  const [showNewCategory, setShowNewCategory] = useState(false); const [newCategoryName, setNewCategoryName] = useState("");
  const [showNewSupplier, setShowNewSupplier] = useState(false); const [newSupplier, setNewSupplier] = useState({ name: "", website: "", notes: "" }); const [supplierSaving, setSupplierSaving] = useState(false); const [supplierError, setSupplierError] = useState("");
  const [evidenceFile, setEvidenceFile] = useState<File | null>(null); const [evidenceViewer, setEvidenceViewer] = useState<{ snapshotId: string; attachments: Attachment[] } | null>(null); const [evidenceLoading, setEvidenceLoading] = useState(false);
  const [archiveCandidate, setArchiveCandidate] = useState<CostComponent | null>(null);
  const selectedCategory = useMemo(() => categories.find((category) => category.id === form.costCategoryId) ?? null, [categories, form.costCategoryId]);
  const genericCategory = isGenericCostCategory(selectedCategory);
  const lodgingCategory = selectedCategory?.code === "LODGING";
  const airfareCategory = selectedCategory?.code === "AIRFARE";
  const baggageCategory = selectedCategory?.code === "BAGGAGE";
  const eventTicketCategory = selectedCategory?.code === "EVENT_TICKET";
  const insuranceCategory = selectedCategory?.code === "INSURANCE";
  const mealsCategory = selectedCategory?.code === "MEALS";
  const tourCategory = selectedCategory?.code === "TOUR";
  const transportationCategory = selectedCategory?.code === "TRANSPORTATION";
  const visaAssistanceCategory = selectedCategory?.code === "VISA_ASSISTANCE";
  const otherCategory = selectedCategory?.code === "OTHER" && selectedCategory.origin === "STANDARD";
  const polishedSpecializedCategory = lodgingCategory || airfareCategory || baggageCategory || eventTicketCategory || insuranceCategory || mealsCategory || tourCategory || transportationCategory || visaAssistanceCategory;
  const selectedComponent = useMemo(() => composition?.components.find((component) => component.id === selectedComponentId) ?? null, [composition, selectedComponentId]);
  const unsupportedHistoricalDetails = Boolean(selectedComponent && selectedCategory && !genericCategory && hasUnsupportedDetailSchema(selectedComponent));
  const standardCategories = categories.filter((category) => category.origin === "STANDARD" && category.code !== "ACCOMMODATION"); const customCategories = categories.filter((category) => category.origin === "CUSTOM");

  useEffect(() => {
    if (!costingProjectId.trim()) { setError("El proyecto de costos solicitado no es válido."); setLoading(false); return; }
    let cancelled = false;
    async function load() {
      setLoading(true); setError(null);
      try {
        const [nextComposition, nextCategories, nextSuppliers] = await Promise.all([getCostComposition(costingProjectId), listCostCategories(), listCostSuppliers()]);
        if (cancelled) return; setProject(nextComposition.project); setComposition(nextComposition); setCategories(nextCategories); setSuppliers(nextSuppliers); onCompositionChanged?.(nextComposition);
      } catch (caught) { if (!cancelled) setError(message(caught, "No se pudo abrir el espacio de costos.")); } finally { if (!cancelled) setLoading(false); }
    }
    void load(); return () => { cancelled = true; };
  }, [costingProjectId, onCompositionChanged, refreshToken]);

  async function refreshComposition() { if (project) setComposition(await getCostComposition(project.id)); }
  function resetForm() { setForm(EMPTY_FORM); setSelectedComponentId(null); setInitialSnapshot(null); setEvidenceFile(null); }
  function selectComponent(componentId: string) {
    const component = composition?.components.find((item) => item.id === componentId); if (!component) return;
    setError(null); setSelectedComponentId(component.id); setInitialSnapshot(component.currentSnapshot); setEvidenceFile(null); setForm(formFromComponent(component));
  }
  async function submitComponent(addAnother: boolean, event?: FormEvent<HTMLFormElement>) {
    event?.preventDefault(); if (!project || !selectedCategory || saving) return;
    try {
      const componentTitle = lodgingCategory ? lodgingComponentTitle(form.details) || form.title.trim() : airfareCategory ? airfareComponentTitle(form.details) || form.title.trim() : baggageCategory ? baggageComponentTitle(form.details) || form.title.trim() : eventTicketCategory ? eventTicketComponentTitle(form.details) || form.title.trim() : insuranceCategory ? insuranceComponentTitle(form.details) || form.title.trim() : mealsCategory ? mealComponentTitle(form.details) || form.title.trim() : tourCategory ? tourComponentTitle(form.details) || form.title.trim() : transportationCategory ? transportationComponentTitle(form.details) || form.title.trim() : visaAssistanceCategory ? visaAssistanceComponentTitle(form.details) || form.title.trim() : form.title.trim();
      validateBaseForm(form, componentTitle); if (eventTicketCategory) validateTicketQuantity(form.quantity); if (mealsCategory) validateMealPeopleQuantity(form.quantity); const details = genericCategory || unsupportedHistoricalDetails || preservesEmptySpecializedDetails(selectedComponent, form.details) ? null : specializedPayload(selectedCategory.code, form.details);
      const structural = { costCategoryId: selectedCategory.id, costSupplierId: form.costSupplierId || null, title: componentTitle, description: form.description.trim() || null, quantity: eventTicketCategory || mealsCategory ? form.quantity.trim() : genericCategory ? form.quantity.trim() || null : selectedComponent?.quantity ?? null, unit: eventTicketCategory || mealsCategory ? null : genericCategory ? form.unit.trim() || null : selectedComponent?.unit ?? null, ...(details ? { detailPayload: details, detailSchemaVersion: 1 } : {}) };
      const monetary = { amount: form.amount.trim(), currency: project.baseCurrency, sourceReference: form.sourceReference.trim() || null, sourceUrl: form.sourceUrl.trim() || null, reason: initialSnapshot?.reason ?? null };
      setSaving(true); setError(null); let snapshotForEvidence = initialSnapshot;
      if (!selectedComponentId) {
        const created = await createGenericCostComponent(project.id, { ...structural, ...monetary }); snapshotForEvidence = created.currentSnapshot;
      } else {
        await updateGenericCostComponent(selectedComponentId, structural);
        if (snapshotChanged(initialSnapshot, monetary)) snapshotForEvidence = (await updateCostComponentCost(selectedComponentId, monetary)).currentSnapshot;
      }
      if (evidenceFile) { if (!snapshotForEvidence) throw new Error("No hay un costo autoritativo disponible para adjuntar el comprobante."); await uploadCostEvidence(snapshotForEvidence.id, evidenceFile); }
      await refreshComposition(); resetForm();
    } catch (caught) { setError(message(caught, "No se pudo guardar el componente.")); } finally { setSaving(false); }
  }
  async function archiveComponent(component: CostComponent) { if (saving) return; setSaving(true); setError(null); try { await archiveCostComponent(component.id); await refreshComposition(); resetForm(); setArchiveCandidate(null); } catch (caught) { setError(message(caught, "No se pudo desactivar el componente.")); } finally { setSaving(false); } }
  async function submitNewCategory(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const displayName = newCategoryName.trim(); if (!displayName || saving) return; setSaving(true); setError(null); try { const created = await createCostCategory({ code: normalizeCustomCostCategoryCode(displayName), displayName }); setCategories((current) => [...current, created].sort((left, right) => left.displayName.localeCompare(right.displayName))); resetForm(); setForm((current) => ({ ...current, costCategoryId: created.id })); setNewCategoryName(""); setShowNewCategory(false); } catch (caught) { setError(message(caught, "No se pudo crear la categoría.")); } finally { setSaving(false); } }
  async function submitNewSupplier(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const name = newSupplier.name.trim(); if (!name || supplierSaving) return; setSupplierSaving(true); setSupplierError(""); try { const created = await createCostSupplier({ name, website: newSupplier.website.trim() || null, notes: newSupplier.notes.trim() || null }); const refreshed = await listCostSuppliers(); setSuppliers(refreshed); setForm((current) => ({ ...current, costSupplierId: created.id })); setNewSupplier({ name: "", website: "", notes: "" }); setShowNewSupplier(false); } catch (caught) { setSupplierError(message(caught, "No se pudo crear el proveedor.")); } finally { setSupplierSaving(false); } }
  async function openEvidence() { if (!initialSnapshot || evidenceLoading) return; setEvidenceLoading(true); setError(null); try { const response = await listCostEvidence(initialSnapshot.id); if (!response.evidence.length) { setError("No hay comprobantes adjuntos."); return; } setEvidenceViewer({ snapshotId: initialSnapshot.id, attachments: response.evidence.map((item) => ({ id: item.id, originalFileName: item.originalFileName, mimeType: item.mimeType })) }); } catch (caught) { setError(message(caught, "No se pudieron cargar los comprobantes.")); } finally { setEvidenceLoading(false); } }
  async function resolveEvidenceUrl(attachment: Attachment, _signal: AbortSignal) { if (!evidenceViewer) throw new Error("No se pudo cargar el comprobante."); return (await getCostEvidenceAccess(evidenceViewer.snapshotId, attachment.id)).url; }

  if (loading) return <div className="grid min-h-[360px] place-items-center text-sm text-muted-foreground">Cargando espacio de costos…</div>;
  if (error && !project) return <Alert variant="destructive"><AlertTitle>No se pudo abrir el espacio de costos</AlertTitle><AlertDescription>{error}</AlertDescription></Alert>;
  if (!project) return null;
  const displayCurrency = project.baseCurrency === baseCurrency ? baseCurrency : project.baseCurrency;
  const supplierField = <div className="space-y-2"><Field label="Proveedor"><Select value={form.costSupplierId} onChange={(event) => setFormField("costSupplierId", event.target.value, setForm)}><option value="">Sin proveedor</option>{suppliers.filter((supplier) => supplier.isActive).map((supplier) => <option key={supplier.id} value={supplier.id}>{supplier.name}</option>)}</Select></Field><Button type="button" variant="outline" size="sm" onClick={() => { setSupplierError(""); setShowNewSupplier(true); }}>+ Nuevo proveedor</Button></div>;
  return <div className="space-y-6">{contextLabel ? <p className="text-sm text-muted-foreground">{contextLabel}</p> : null}{error ? <Alert variant="destructive"><AlertTitle>Acción no completada</AlertTitle><AlertDescription>{error}</AlertDescription></Alert> : null}<div className="grid gap-6 lg:grid-cols-[minmax(0,1.3fr)_minmax(320px,0.7fr)]"><section className="space-y-6">
      {canEdit ? <> <Card><CardHeader><CardTitle>{selectedComponentId ? "Editar componente" : "Agregar componente"}</CardTitle></CardHeader><CardContent>
        <div className="mb-5 flex flex-wrap items-end gap-3"><label className="min-w-[220px] flex-1 text-sm font-medium">Categoría<Select value={form.costCategoryId} onChange={(event) => { resetForm(); setForm((current) => ({ ...current, costCategoryId: event.target.value })); }}><option value="">Selecciona una categoría</option><optgroup label="Estándar">{standardCategories.map((category) => <option key={category.id} value={category.id}>{costCategoryDisplayName(category)}</option>)}</optgroup>{customCategories.length ? <optgroup label="Personalizadas">{customCategories.map((category) => <option key={category.id} value={category.id}>{costCategoryDisplayName(category)}</option>)}</optgroup> : null}</Select></label><Button type="button" variant="outline" onClick={() => setShowNewCategory((value) => !value)}>+ Crear nueva opción</Button></div>
        {showNewCategory ? <form className="mb-5 rounded-lg border border-border bg-muted p-4" onSubmit={submitNewCategory}><label className="block text-sm font-medium">Nombre de la nueva opción<Input value={newCategoryName} onChange={(event) => setNewCategoryName(event.target.value)} placeholder="Ej. Trámite consular" /></label><div className="mt-3 flex gap-2"><Button type="submit" size="sm" disabled={saving || !newCategoryName.trim()}>Crear categoría</Button><Button type="button" size="sm" variant="ghost" onClick={() => setShowNewCategory(false)}>Cancelar</Button></div></form> : null}
        {!selectedCategory ? <p className="text-sm text-muted-foreground">Selecciona una categoría para cargar el formulario.</p> : <form className="space-y-4" onSubmit={(event) => void submitComponent(false, event)}>
          {unsupportedHistoricalDetails ? <Alert variant="info"><AlertTitle>Detalles históricos sin modificar</AlertTitle><AlertDescription>Este componente usa el esquema v{selectedComponent?.detailSchemaVersion ?? "desconocido"}. Puedes actualizar sus datos generales o costo, pero sus detalles especializados se conservan sin reinterpretarlos.</AlertDescription></Alert> : null}
          {!polishedSpecializedCategory && !otherCategory ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Título *"><Input value={form.title} onChange={(event) => setFormField("title", event.target.value, setForm)} /></Field>{supplierField}</div> : null}
          {!polishedSpecializedCategory && !otherCategory ? <Field label="Observaciones"><Textarea value={form.description} onChange={(event) => setFormField("description", event.target.value, setForm)} /></Field> : null}
          {!genericCategory && !unsupportedHistoricalDetails ? polishedSpecializedCategory ? <section className="space-y-3"><p className="text-sm font-medium">{lodgingCategory ? "Datos del hospedaje" : airfareCategory ? "Datos del vuelo" : baggageCategory ? "Datos del equipaje" : eventTicketCategory ? "Datos del evento" : insuranceCategory ? "Datos del seguro" : mealsCategory ? "Datos de alimentación" : tourCategory ? "Datos del tour" : transportationCategory ? "Datos del transporte" : "Datos de visa"}</p><SpecializedDetailsFields code={selectedCategory.code} values={form.details} quantity={form.quantity} onQuantityChange={(value) => setFormField("quantity", value, setForm)} onChange={(field, value) => setForm((current) => ({ ...current, details: { ...current.details, [field]: value } }))} /></section> : <SpecializedDetailsFields code={selectedCategory.code} values={form.details} quantity={form.quantity} onQuantityChange={(value) => setFormField("quantity", value, setForm)} onChange={(field, value) => setForm((current) => ({ ...current, details: { ...current.details, [field]: value } }))} /> : null}
          {genericCategory && !otherCategory ? <div className="grid gap-4 sm:grid-cols-2"><Field label="Cantidad"><Input inputMode="decimal" value={form.quantity} onChange={(event) => setFormField("quantity", event.target.value, setForm)} placeholder="Ej. 2" /></Field><Field label="Unidad"><Input value={form.unit} onChange={(event) => setFormField("unit", event.target.value, setForm)} placeholder="Ej. noches, unidades" /></Field></div> : null}
          {polishedSpecializedCategory ? <><section className="space-y-3"><p className="text-sm font-medium">Costo y proveedor</p><div className="grid gap-4 sm:grid-cols-2"><Field label={`Costo * (${displayCurrency})`}><Input inputMode="decimal" value={form.amount} onChange={(event) => setFormField("amount", event.target.value, setForm)} placeholder="0.00" /></Field>{supplierField}</div></section><section className="space-y-3"><p className="text-sm font-medium">Información de respaldo</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Referencia (opcional)"><Input value={form.sourceReference} onChange={(event) => setFormField("sourceReference", event.target.value, setForm)} placeholder={airfareCategory ? "Ej. Cotización, localizador, correo o referencia de tarifa" : baggageCategory ? "Ej. Cotización, correo, WhatsApp o referencia del proveedor" : eventTicketCategory ? "Ej. Reserva, localizador, cotización, correo o WhatsApp" : insuranceCategory ? "Ej. Póliza, cotización, correo o referencia del proveedor" : mealsCategory ? "Ej. Cotización, menú, correo, WhatsApp o referencia del proveedor" : tourCategory ? "Ej. Cotización, reserva, correo o WhatsApp" : transportationCategory ? "Ej. Cotización, reserva, correo, WhatsApp o referencia del proveedor" : visaAssistanceCategory ? "Ej. Cotización, trámite, correo, WhatsApp o referencia del proveedor" : "Ej. Cotización #1234, correo, WhatsApp o código de reserva"} /></Field><Field label="URL de fuente (opcional)"><Input type="url" value={form.sourceUrl} onChange={(event) => setFormField("sourceUrl", event.target.value, setForm)} placeholder="https://..." /></Field></div><EvidenceFields title="Comprobante (opcional)" loading={evidenceLoading} file={evidenceFile} existingSnapshot={initialSnapshot} onFile={setEvidenceFile} onOpen={openEvidence} /></section><Field label="Observaciones"><Textarea value={form.description} onChange={(event) => setFormField("description", event.target.value, setForm)} /></Field></> : otherCategory ? <><section className="space-y-3"><p className="text-sm font-medium">Datos del costo</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Título *"><Input value={form.title} onChange={(event) => setFormField("title", event.target.value, setForm)} placeholder="Ej. Tasa portuaria, propina obligatoria, permiso especial" /></Field><Field label="Cantidad (opcional)"><Input inputMode="decimal" value={form.quantity} onChange={(event) => setFormField("quantity", event.target.value, setForm)} placeholder="Ej. 2" /></Field><Field label="Unidad (opcional)"><Input value={form.unit} onChange={(event) => setFormField("unit", event.target.value, setForm)} placeholder="Ej. unidades, noches, días, personas" /></Field></div></section><section className="space-y-3"><p className="text-sm font-medium">Costo y proveedor</p><div className="grid gap-4 sm:grid-cols-2"><Field label={`Costo * (${displayCurrency})`}><Input inputMode="decimal" value={form.amount} onChange={(event) => setFormField("amount", event.target.value, setForm)} placeholder="0.00" /></Field>{supplierField}</div></section><section className="space-y-3"><p className="text-sm font-medium">Información de respaldo</p><div className="grid gap-4 sm:grid-cols-2"><Field label="Referencia (opcional)"><Input value={form.sourceReference} onChange={(event) => setFormField("sourceReference", event.target.value, setForm)} placeholder="Ej. Cotización, correo, WhatsApp o referencia del proveedor" /></Field><Field label="URL de fuente (opcional)"><Input type="url" value={form.sourceUrl} onChange={(event) => setFormField("sourceUrl", event.target.value, setForm)} placeholder="https://..." /></Field></div><EvidenceFields title="Comprobante (opcional)" loading={evidenceLoading} file={evidenceFile} existingSnapshot={initialSnapshot} onFile={setEvidenceFile} onOpen={openEvidence} /></section><Field label="Observaciones"><Textarea value={form.description} onChange={(event) => setFormField("description", event.target.value, setForm)} /></Field></> : <><div className="grid gap-4 sm:grid-cols-2"><Field label={`Costo * (${displayCurrency})`}><Input inputMode="decimal" value={form.amount} onChange={(event) => setFormField("amount", event.target.value, setForm)} placeholder="0.00" /></Field><Field label="Referencia / fuente"><Input value={form.sourceReference} onChange={(event) => setFormField("sourceReference", event.target.value, setForm)} /></Field></div><Field label="URL de fuente"><Input type="url" value={form.sourceUrl} onChange={(event) => setFormField("sourceUrl", event.target.value, setForm)} placeholder="https://" /></Field><EvidenceFields loading={evidenceLoading} file={evidenceFile} existingSnapshot={initialSnapshot} onFile={setEvidenceFile} onOpen={openEvidence} /></>}
          <div className="flex flex-wrap gap-2"><Button type="submit" disabled={saving}>{saving ? "Guardando…" : "Guardar"}</Button><Button type="button" variant="outline" disabled={saving} onClick={() => void submitComponent(true)}>Guardar y agregar otro</Button><Button type="button" variant="ghost" onClick={resetForm}>Cancelar</Button></div>
        </form>}
      </CardContent></Card> </> : null}
      <Card><CardHeader><CardTitle>Componentes guardados</CardTitle>{canEdit ? <Button type="button" variant="outline" size="sm" onClick={resetForm}>Agregar componente</Button> : null}</CardHeader><CardContent className="space-y-2">{composition?.components.length ? composition.components.map((component) => <ComponentRow key={component.id} component={component} project={project} canEdit={canEdit} onSelect={selectComponent} onArchive={() => setArchiveCandidate(component)} />) : <p className="py-6 text-center text-sm text-muted-foreground">Aún no hay componentes activos. Agrega el primero para comenzar.</p>}</CardContent></Card>
    </section><CompositionSummary composition={composition} project={project} /></div>{evidenceViewer ? <AttachmentViewer attachments={evidenceViewer.attachments} resolveAttachmentUrl={resolveEvidenceUrl} onClose={() => setEvidenceViewer(null)} /> : null}<Dialog open={Boolean(archiveCandidate)} onOpenChange={(open) => { if (!open) setArchiveCandidate(null); }}><DialogContent><DialogHeader><DialogTitle>Desactivar componente</DialogTitle><DialogDescription>El componente dejará de contribuir al costo autoritativo. Sus costos, comprobantes y auditoría se conservarán.</DialogDescription></DialogHeader>{archiveCandidate ? <p className="rounded-md bg-muted p-3 text-sm font-medium">{archiveCandidate.title}</p> : null}<DialogFooter><Button type="button" variant="outline" onClick={() => setArchiveCandidate(null)} disabled={saving}>Cancelar</Button><Button type="button" variant="destructive" onClick={() => archiveCandidate && void archiveComponent(archiveCandidate)} disabled={saving}>{saving ? "Desactivando…" : "Desactivar componente"}</Button></DialogFooter></DialogContent></Dialog><Dialog open={showNewSupplier} onOpenChange={setShowNewSupplier}><DialogContent><DialogHeader><DialogTitle>Nuevo proveedor</DialogTitle><DialogDescription>Registra un proveedor de costos para este tenant. Puede ser manual o sin sitio web.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={(event) => void submitNewSupplier(event)}>{supplierError ? <Alert variant="destructive"><AlertDescription>{supplierError}</AlertDescription></Alert> : null}<Field label="Nombre *"><Input value={newSupplier.name} onChange={(event) => setNewSupplier((current) => ({ ...current, name: event.target.value }))} disabled={supplierSaving} autoFocus /></Field><Field label="Sitio web (opcional)"><Input type="url" value={newSupplier.website} onChange={(event) => setNewSupplier((current) => ({ ...current, website: event.target.value }))} disabled={supplierSaving} placeholder="https://" /></Field><Field label="Notas (opcional)"><Textarea value={newSupplier.notes} onChange={(event) => setNewSupplier((current) => ({ ...current, notes: event.target.value }))} disabled={supplierSaving} /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setShowNewSupplier(false)} disabled={supplierSaving}>Cancelar</Button><Button type="submit" disabled={supplierSaving || !newSupplier.name.trim()}>{supplierSaving ? "Creando…" : "Crear proveedor"}</Button></DialogFooter></form></DialogContent></Dialog></div>;
}
function ComponentRow({ component, project, canEdit, onSelect, onArchive }: { component: CostComponent; project: CostingProject; canEdit: boolean; onSelect: (id: string) => void; onArchive: () => void }) { return <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-border p-3"><button type="button" onClick={() => onSelect(component.id)} className="min-w-0 flex-1 text-left"><span className="block truncate text-sm font-medium">{component.title}</span><span className="block truncate text-xs text-muted-foreground">{costCategoryDisplayName(component.costCategory)}{component.costSupplier ? ` · ${component.costSupplier.name}` : ""}</span></button><div className="flex items-center gap-2"><span className="text-right"><span className="block text-sm font-medium">{component.currentSnapshot ? formatFinanceMoneyDisplay(component.currentSnapshot.amount, project.baseCurrency) : "Sin costo"}</span><Badge variant="success">{componentStatusLabel(component.status)}</Badge></span>{canEdit ? <div className="flex gap-1"><Button type="button" variant="outline" size="sm" onClick={() => onSelect(component.id)}>Editar</Button><Button type="button" variant="outline" size="sm" onClick={onArchive}>Desactivar componente</Button></div> : null}</div></div>; }
function CompositionSummary({ composition, project }: { composition: CostComposition | null; project: CostingProject }) { return <aside><Card className="sticky top-4"><CardHeader><CardTitle>Resumen de composición</CardTitle></CardHeader><CardContent className="space-y-4"><div><p className="text-sm text-muted-foreground">Costo total autoritativo</p><p className="text-2xl font-semibold">{formatFinanceMoneyDisplay(composition?.authoritativeTotalCost ?? "0", project.baseCurrency)}</p></div><div className="border-t border-border pt-4"><p className="text-sm font-medium">Subtotales por categoría</p><div className="mt-2 space-y-2 text-sm">{composition?.categorySubtotals.map((subtotal) => <div key={subtotal.category.id} className="flex justify-between gap-3"><span className="text-muted-foreground">{costCategoryDisplayName(subtotal.category)}</span><span className="font-medium">{formatFinanceMoneyDisplay(subtotal.amount, project.baseCurrency)}</span></div>) ?? <p className="text-muted-foreground">Sin subtotales todavía.</p>}</div></div><div className="border-t border-border pt-4"><p className="text-sm font-medium">Componentes activos ({composition?.total ?? 0})</p><div className="mt-2 space-y-3">{composition?.components.map((component) => <div key={component.id} className="rounded-md bg-muted p-3"><p className="text-xs font-medium text-muted-foreground">{costCategoryDisplayName(component.costCategory)}</p><div className="mt-1 flex justify-between gap-3"><p className="min-w-0 truncate text-sm font-medium">{component.title}</p><p className="shrink-0 text-sm font-medium">{component.currentSnapshot ? formatFinanceMoneyDisplay(component.currentSnapshot.amount, project.baseCurrency) : "Sin costo"}</p></div><p className="mt-1 text-xs text-muted-foreground">{specializedDescription(component)}</p>{component.costSupplier ? <p className="mt-1 text-xs text-muted-foreground">Proveedor: {component.costSupplier.name}</p> : null}</div>) ?? <p className="text-sm text-muted-foreground">Aún no hay componentes activos.</p>}</div></div></CardContent></Card></aside>; }

function SpecializedDetailsFields({ code, values, quantity, onQuantityChange, onChange }: { code: string; values: DetailValues; quantity: string; onQuantityChange: (value: string) => void; onChange: (field: string, value: string) => void }) {
  const required = (field: string) => requiredDetailField(code, field) || ((code === "AIRFARE" || code === "TRANSPORTATION") && field === "returnDate" && values.tripType === "ROUND_TRIP");
  const text = (label: string, field: string, type = "text", placeholder?: string) => <Field label={`${label}${required(field) ? " *" : ""}`}><Input type={type} value={values[field] ?? ""} onChange={(event) => onChange(field, event.target.value)} placeholder={placeholder} /></Field>;
  const select = (label: string, field: keyof typeof ENUMS) => <Field label={`${label}${required(field) ? " *" : ""}`}><Select value={values[field] ?? ""} onChange={(event) => onChange(field, event.target.value)}><option value="">Selecciona una opción</option>{ENUMS[field].map((value) => <option key={value} value={value}>{enumLabel(value, field)}</option>)}</Select></Field>;
  switch (code) {
    case "AIRFARE": return <DetailGrid>{select("Tipo de vuelo", "flightType")}{select("Tipo de trayecto", "tripType")}<AirportLocationField label="Origen" value={values.origin ?? ""} onChange={(selection) => onChange("origin", airportSelectionValue(selection))} /><AirportLocationField label="Destino" value={values.destination ?? ""} onChange={(selection) => onChange("destination", airportSelectionValue(selection))} />{text("Fecha de salida", "departureDate", "date")}{values.tripType === "ROUND_TRIP" ? text("Fecha de regreso", "returnDate", "date") : null}{text("Aerolínea", "airline")}{select("Cabina", "cabinClass")}</DetailGrid>;
    case "BAGGAGE": return <DetailGrid>{select("Tipo de equipaje", "baggageType")}{text("Piezas", "pieces", "number")}{text("Peso (kg)", "weightKg", "text", "Ej. 23.5")}</DetailGrid>;
    case "LODGING": return <DetailGrid>{text("Nombre del alojamiento", "propertyName")}{text("Ciudad", "city")}{select("Tipo de hospedaje", "lodgingType")}{select("Tipo de habitación", "roomType")}{text("Check-in", "checkIn", "date")}{text("Check-out", "checkOut", "date")}{text("Noches", "nights", "number")}{text("Cantidad de habitaciones", "roomCount", "number")}</DetailGrid>;
    case "TRANSPORTATION": return <DetailGrid>{select("Tipo de transporte", "transportationType")}{select("Tipo de trayecto", "tripType")}{text("Origen", "origin")}{text("Destino", "destination")}{text("Fecha de servicio", "serviceDate", "date")}{text("Hora", "serviceTime", "time")}{values.tripType === "ROUND_TRIP" ? text("Fecha de regreso", "returnDate", "date") : null}</DetailGrid>;
    case "TOUR": return <DetailGrid>{text("Actividad / tour", "activityName")}{select("Tipo de tour", "tourType")}{text("Ubicación", "location")}{text("Fecha de servicio", "serviceDate", "date")}</DetailGrid>;
    case "INSURANCE": return <DetailGrid>{select("Tipo de cobertura", "coverageType")}{text("Inicio de vigencia", "startDate", "date")}{text("Fin de vigencia", "endDate", "date")}{text("Monto de cobertura", "coverageAmount", "text", "Ej. 50000")}</DetailGrid>;
    case "EVENT_TICKET": return <DetailGrid>{text("Evento", "eventName")}{text("Recinto / lugar", "venue")}{text("Ciudad", "city")}{text("Fecha del evento", "eventDate", "date")}<Field label="Cantidad de entradas *"><Input type="number" min="1" step="1" inputMode="numeric" value={quantity} onChange={(event) => onQuantityChange(event.target.value)} /></Field></DetailGrid>;
    case "VISA_ASSISTANCE": return <DetailGrid><VisaDestinationCountryField value={values.destinationCountry ?? ""} onChange={(value) => onChange("destinationCountry", value)} />{select("Tipo de visa", "visaType")}{text("Fecha esperada de viaje", "expectedTravelDate", "date")}</DetailGrid>;
    case "MEALS": return <DetailGrid>{select("Plan de comidas", "mealPlanType")}{text("Fecha de inicio", "startDate", "date")}{text("Fecha final", "endDate", "date")}<Field label="Cantidad de personas *"><Input type="number" min="1" step="1" inputMode="numeric" value={quantity} onChange={(event) => onQuantityChange(event.target.value)} /></Field></DetailGrid>;
    default: return null;
  }
}
function airportSelectionValue(selection: AirportLocationSelection) { return selection.kind === "STANDARD" ? selection.airport.iata : selection.value; }
function EvidenceFields({ title = "Comprobante", loading, file, existingSnapshot, onFile, onOpen }: { title?: string; loading: boolean; file: File | null; existingSnapshot: CostSnapshot | null; onFile: (file: File | null) => void; onOpen: () => void }) { return <div className="rounded-lg border border-border p-4"><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">PDF, JPG, PNG o WEBP; máximo 10 MB. Se adjunta al costo autoritativo actual.</p><Input className="mt-3" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" onChange={(event) => onFile(event.target.files?.[0] ?? null)} />{file ? <p className="mt-2 text-xs text-muted-foreground">Pendiente de adjuntar: {file.name}</p> : null}{existingSnapshot ? <div className="mt-3 border-t border-border pt-3"><Button type="button" variant="outline" size="sm" disabled={loading} onClick={onOpen}>{loading ? "Cargando comprobantes…" : "Ver comprobante"}</Button></div> : null}</div>; }
function DetailGrid({ children }: { children: ReactNode }) { return <div className="grid gap-4 rounded-lg border border-border p-4 sm:grid-cols-2">{children}</div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="block text-sm font-medium text-foreground"><span className="mb-1 block">{label}</span>{children}</label>; }
function VisaDestinationCountryField({ value, onChange }: { value: string; onChange: (value: string) => void }) { const [manual, setManual] = useState(() => Boolean(value && !getSpanishCountryName(value))); useEffect(() => { if (value && !getSpanishCountryName(value)) setManual(true); }, [value]); return manual ? <Field label="País de destino *"><Input value={value} onChange={(event) => onChange(event.target.value)} placeholder="Ej. Egipto" /><Button type="button" variant="ghost" size="sm" className="mt-1" onClick={() => { onChange(""); setManual(false); }}>Buscar en la lista de países</Button></Field> : <div className="space-y-1"><CountrySelect label="País de destino" placeholder="Buscar país" required value={value} onChange={onChange} /><Button type="button" variant="ghost" size="sm" onClick={() => { onChange(""); setManual(true); }}>Ingresar manualmente</Button></div>; }
function setFormField<Key extends Exclude<keyof CostForm, "details">>(key: Key, value: CostForm[Key], setForm: Dispatch<SetStateAction<CostForm>>) { setForm((current) => ({ ...current, [key]: value })); }
function formFromComponent(component: CostComponent): CostForm { const snapshot = component.currentSnapshot; const details = component.detailSchemaVersion === 1 ? detailsFromPayload(component.detailPayload) : {}; if (component.costCategory.code === "INSURANCE" && details.coverageType === "TRIP_CANCELLATION") details.coverageType = "CANCELLATION"; if (component.costCategory.code === "TRANSPORTATION") { details.transportationType = ({ SHARED_TRANSFER: "SHARED_SHUTTLE", CAR_RENTAL: "RENTAL_CAR", RAIL: "TRAIN" } as Record<string, string>)[details.transportationType] ?? details.transportationType; } if (component.costCategory.code === "VISA_ASSISTANCE" && details.visaType === "TOURIST") details.visaType = "TOURISM"; return { costCategoryId: component.costCategory.id, costSupplierId: component.costSupplier?.id ?? "", title: component.title, description: component.description ?? "", quantity: component.quantity ?? "", unit: component.unit ?? "", amount: snapshot?.amount ?? "", sourceReference: snapshot?.sourceReference ?? "", sourceUrl: snapshot?.sourceUrl ?? "", details }; }
function detailsFromPayload(payload: Record<string, unknown> | null): DetailValues { return Object.fromEntries(Object.entries(payload ?? {}).map(([key, value]) => [key, String(value)])); }
function snapshotChanged(snapshot: CostSnapshot | null, next: { amount: string; currency: string; sourceReference: string | null; sourceUrl: string | null; reason: string | null }) { return !snapshot || snapshot.amount !== next.amount || snapshot.currency !== next.currency || snapshot.sourceReference !== next.sourceReference || snapshot.sourceUrl !== next.sourceUrl || snapshot.reason !== next.reason; }
function hasUnsupportedDetailSchema(component: CostComponent) { return (component.detailPayload !== null || component.detailSchemaVersion !== null) && component.detailSchemaVersion !== 1; }
function preservesEmptySpecializedDetails(component: CostComponent | null, details: DetailValues) { return Boolean(component && component.detailPayload === null && component.detailSchemaVersion === null && !Object.values(details).some((value) => value.trim())); }
function validateBaseForm(form: CostForm, title = form.title) { if (!title.trim()) throw new Error("El título es requerido."); if (!MONEY_PATTERN.test(form.amount.trim())) throw new Error("El costo debe ser un decimal exacto de hasta cinco decimales."); if (form.quantity.trim() && (!MONEY_PATTERN.test(form.quantity.trim()) || /^0(?:\.0+)?$/.test(form.quantity.trim()))) throw new Error("La cantidad debe ser un decimal exacto mayor que cero."); }
function validateTicketQuantity(value: string) { if (!/^\d+$/.test(value.trim()) || !Number.isSafeInteger(Number(value)) || Number(value) <= 0) throw new Error("La cantidad de entradas debe ser un entero positivo."); }
function validateMealPeopleQuantity(value: string) { if (!/^\d+$/.test(value.trim()) || !Number.isSafeInteger(Number(value)) || Number(value) <= 0) throw new Error("La cantidad de personas debe ser un entero positivo."); }
function lodgingComponentTitle(values: DetailValues) { return [values.propertyName?.trim(), values.city?.trim()].filter(Boolean).join(" - "); }
function airfareComponentTitle(values: DetailValues) { return [values.origin?.trim(), values.destination?.trim()].filter(Boolean).join(" → "); }
function baggageComponentTitle(values: DetailValues) { return enumLabel(values.baggageType ?? "", "baggageType"); }
function eventTicketComponentTitle(values: DetailValues) { return [values.eventName?.trim(), values.city?.trim()].filter(Boolean).join(" - "); }
function insuranceComponentTitle(values: DetailValues) { return ({ MEDICAL: "Seguro médico", CANCELLATION: "Seguro de cancelación", TRIP_CANCELLATION: "Seguro de cancelación", BAGGAGE: "Seguro de equipaje", COMPREHENSIVE: "Seguro integral", OTHER: "Seguro" } as Record<string, string>)[values.coverageType?.trim().toUpperCase() ?? ""] ?? ""; }
function mealComponentTitle(values: DetailValues) { return ({ BREAKFAST: "Desayuno", LUNCH: "Almuerzo", DINNER: "Cena", HALF_BOARD: "Media pensión", FULL_BOARD: "Pensión completa", ALL_INCLUSIVE: "Todo incluido", OTHER: "Alimentación" } as Record<string, string>)[values.mealPlanType?.trim().toUpperCase() ?? ""] ?? ""; }
function tourComponentTitle(values: DetailValues) { return values.activityName?.trim() ?? ""; }
function transportationComponentTitle(values: DetailValues) { return [values.origin?.trim(), values.destination?.trim()].filter(Boolean).join(" → "); }
function visaAssistanceComponentTitle(values: DetailValues) { const country = getSpanishCountryName(values.destinationCountry ?? "") ?? values.destinationCountry?.trim(); const prefix = ({ TOURISM: "Visa turística", TOURIST: "Visa turística", BUSINESS: "Visa de negocios", TRANSIT: "Visa de tránsito", STUDENT: "Visa de estudios", WORK: "Visa de trabajo", OTHER: "Asistencia de visa" } as Record<string, string>)[values.visaType?.trim().toUpperCase() ?? ""]; return [prefix, country].filter(Boolean).join(" - "); }

function specializedPayload(code: string, values: DetailValues): Record<string, unknown> {
  const string = (field: string) => requiredString(values, field); const date = (field: string) => requiredDate(values, field); const optionalDate = (field: string) => optional(values, field, (value) => requireIsoDate(value, field)); const optionalString = (field: string) => optional(values, field, (value) => requireText(value, field)); const optionalDecimal = (field: string) => optional(values, field, positiveDecimal); const optionalEnum = (field: keyof typeof ENUMS) => optional(values, field, (value) => enumValue(value, field));
  switch (code) {
    case "AIRFARE": { const tripType = enumValue(string("tripType"), "tripType"); const departureDate = date("departureDate"); const returnDate = tripType === "ROUND_TRIP" ? date("returnDate") : undefined; assertDateOrder(departureDate, returnDate, "returnDate", "departureDate"); return compact({ flightType: enumValue(string("flightType"), "flightType"), tripType, origin: string("origin"), destination: string("destination"), departureDate, returnDate, airline: optionalString("airline"), cabinClass: optionalEnum("cabinClass") }); }
    case "BAGGAGE": return compact({ baggageType: enumValue(string("baggageType"), "baggageType"), pieces: positiveInteger(values, "pieces"), weightKg: optionalDecimal("weightKg") });
    case "LODGING": { const checkIn = date("checkIn"); const checkOut = date("checkOut"); assertDateOrder(checkIn, checkOut, "checkOut", "checkIn"); return { propertyName: string("propertyName"), city: string("city"), lodgingType: enumValue(string("lodgingType"), "lodgingType"), roomType: enumValue(string("roomType"), "roomType"), checkIn, checkOut, nights: positiveInteger(values, "nights"), roomCount: positiveInteger(values, "roomCount") }; }
    case "TRANSPORTATION": { const tripType = enumValue(string("tripType"), "tripType"); const serviceDate = date("serviceDate"); const returnDate = tripType === "ROUND_TRIP" ? date("returnDate") : optionalDate("returnDate"); assertDateOrder(serviceDate, returnDate, "returnDate", "serviceDate"); return compact({ transportationType: enumValue(string("transportationType"), "transportationType"), tripType, origin: string("origin"), destination: string("destination"), serviceDate, serviceTime: optional(values, "serviceTime", time), returnDate }); }
    case "TOUR": return compact({ activityName: string("activityName"), tourType: enumValue(string("tourType"), "tourType"), location: string("location"), serviceDate: date("serviceDate"), duration: optionalString("duration") });
    case "INSURANCE": { const startDate = date("startDate"); const endDate = date("endDate"); assertDateOrder(startDate, endDate, "endDate", "startDate"); return compact({ coverageType: enumValue(string("coverageType"), "coverageType"), startDate, endDate, coverageAmount: optionalDecimal("coverageAmount") }); }
    case "EVENT_TICKET": return { eventName: string("eventName"), venue: string("venue"), city: string("city"), eventDate: date("eventDate") };
    case "VISA_ASSISTANCE": return { destinationCountry: string("destinationCountry"), visaType: enumValue(string("visaType"), "visaType"), expectedTravelDate: date("expectedTravelDate") };
    case "MEALS": { const startDate = date("startDate"); const endDate = optionalDate("endDate"); assertDateOrder(startDate, endDate, "endDate", "startDate"); return compact({ mealPlanType: enumValue(string("mealPlanType"), "mealPlanType"), startDate, endDate }); }
    default: throw new Error("La categoría no tiene un contrato especializado compatible.");
  }
}
function requiredString(values: DetailValues, field: string) { const value = values[field]?.trim(); if (!value) throw new Error(`${field} es requerido.`); return value; }
function requireText(value: string, field: string) { if (!value.trim()) throw new Error(`${field} es requerido.`); return value.trim(); }
function requireIsoDate(value: string, field: string) { if (!isIsoDate(value)) throw new Error(`${field} debe usar una fecha válida AAAA-MM-DD.`); return value; }
function requiredDate(values: DetailValues, field: string) { return requireIsoDate(requiredString(values, field), field); }
function optional<T>(values: DetailValues, field: string, normalize: (value: string) => T): T | undefined { const value = values[field]?.trim(); return value ? normalize(value) : undefined; }
function positiveInteger(values: DetailValues, field: string) { const value = requiredString(values, field); if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || Number(value) < 1) throw new Error(`${field} debe ser un entero positivo.`); return Number(value); }
function positiveDecimal(value: string) { if (!MONEY_PATTERN.test(value) || /^0(?:\.0+)?$/.test(value)) throw new Error("El valor debe ser un decimal exacto positivo."); return value; }
function enumValue(value: string, field: keyof typeof ENUMS) { const normalized = value.trim().toUpperCase(); if (!(ENUMS[field] as readonly string[]).includes(normalized)) throw new Error(`${field} tiene un valor no válido.`); return normalized; }
function time(value: string) { if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(value)) throw new Error("La hora debe usar formato HH:mm."); return value; }
function isIsoDate(value: string) { if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false; const [year, month, day] = value.split("-").map(Number); const date = new Date(Date.UTC(year, month - 1, day)); return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day; }
function assertDateOrder(start: string | undefined, end: string | undefined, endLabel: string, startLabel: string) { if (start && end && end < start) throw new Error(`${endLabel} no puede ser anterior a ${startLabel}.`); }
function compact(value: Record<string, unknown>) { return Object.fromEntries(Object.entries(value).filter(([, item]) => item !== undefined)); }
function requiredDetailField(code: string, field: string) { return SPECIALIZED_CODES.has(code) && !OPTIONAL_DETAIL_FIELDS[code]?.includes(field); }
function enumLabel(value: string, field?: keyof typeof ENUMS) { if (field === "cabinClass" && value === "OTHER") return "Otra"; if (field === "visaType" && value === "BUSINESS") return "Negocios"; return ENUM_LABELS[value] ?? value.replaceAll("_", " "); }
function componentStatusLabel(status: CostComponent["status"]) { return status === "ACTIVE" ? "Activo" : "Desactivado"; }
function projectStatusLabel(status: string) { return ({ DRAFT: "Borrador", ACTIVE: "Activo", ARCHIVED: "Archivado" } as Record<string, string>)[status] ?? status; }
function specializedDescription(component: CostComponent) {
  if (!SPECIALIZED_CODES.has(component.costCategory.code)) return component.costCategory.code === "OTHER" ? (component.quantity && component.unit ? `${component.quantity} ${component.unit}` : component.description || "Sin descripción adicional") : component.description || (component.quantity && component.unit ? `${component.quantity} ${component.unit}` : "Sin descripción adicional");
  if (component.detailSchemaVersion !== 1 || !component.detailPayload) return `Detalles especializados v${component.detailSchemaVersion ?? "sin versión"}`;
  const detail = component.detailPayload; const text = (field: string) => typeof detail[field] === "string" || typeof detail[field] === "number" ? String(detail[field]) : "";
  switch (component.costCategory.code) {
    case "AIRFARE": return [[text("origin"), text("destination")].filter(Boolean).join(" → "), enumLabel(text("flightType")), text("departureDate")].filter(Boolean).join(" · ") || "Itinerario";
    case "BAGGAGE": return [text("pieces") && `${text("pieces")} ${text("pieces") === "1" ? "pieza" : "piezas"}`, text("weightKg") && `${text("weightKg")} kg`].filter(Boolean).join(" · ");
    case "LODGING": return [text("propertyName"), text("city"), enumLabel(text("lodgingType")), enumLabel(text("roomType")), text("checkIn") && `${text("checkIn")} — ${text("checkOut")}`].filter(Boolean).join(" · ");
    case "TRANSPORTATION": return [enumLabel(text("transportationType")), enumLabel(text("tripType")), text("serviceDate") && formatBusinessDate(text("serviceDate")), text("serviceTime")].filter(Boolean).join(" · ");
    case "TOUR": return [enumLabel(text("tourType")), text("location"), text("serviceDate") && formatBusinessDate(text("serviceDate"))].filter(Boolean).join(" · ");
    case "INSURANCE": return [text("startDate") && `${formatBusinessDate(text("startDate"))}${text("endDate") ? ` → ${formatBusinessDate(text("endDate"))}` : ""}`, text("coverageAmount") && `Monto de cobertura: ${text("coverageAmount")}`].filter(Boolean).join(" · ");
    case "EVENT_TICKET": return ["Entradas", component.quantity && `${component.quantity} ${component.quantity === "1" ? "entrada" : "entradas"}`, text("eventDate") && formatBusinessDate(text("eventDate"))].filter(Boolean).join(" · ");
    case "VISA_ASSISTANCE": return [text("expectedTravelDate") && `Viaje previsto: ${formatBusinessDate(text("expectedTravelDate"))}`].filter(Boolean).join(" · ");
    case "MEALS": return [text("startDate") && `${formatBusinessDate(text("startDate"))}${text("endDate") ? ` → ${formatBusinessDate(text("endDate"))}` : ""}`, component.quantity && `${component.quantity} ${component.quantity === "1" ? "persona" : "personas"}`].filter(Boolean).join(" · ");
    default: return "Detalles especializados";
  }
}
function message(error: unknown, fallback: string) { const value = String((error as { message?: unknown })?.message ?? "").trim(); return value || fallback; }
